import type { MetadataRoute } from 'next';

// Generated by app-engine: scripts/add-seo-surface.mjs
// Add every public page here. /venue and /reset are private (noindex) and stay out.
import { SITE_URL } from '@/lib/seo';

// Always the production host, so a preview build never lists itself.
const BASE_URL = SITE_URL;

const ROUTES: Array<{ path: string; priority: number }> = [
  { path: '/', priority: 1 },
  { path: '/playdates', priority: 0.9 },
  { path: '/toy-swap', priority: 0.9 },
  { path: '/maps', priority: 0.8 },
  { path: '/privacy', priority: 0.5 },
  { path: '/terms', priority: 0.5 },
];

export default function sitemap(): MetadataRoute.Sitemap {
  const lastModified = new Date();
  return ROUTES.map(({ path, priority }) => ({
    url: `${BASE_URL}${path === '/' ? '' : path}`,
    lastModified,
    changeFrequency: priority === 1 ? 'weekly' : 'monthly',
    priority,
  }));
}
